import { basename } from './path_utils.mjs';

class CliExit extends Error {
  constructor(code, stream, content) {
    super(content);
    this.code = code;
    this.stream = stream;
    this.content = content;
  }
}

const OPTION_NAMES = ['--a', '--b', '--c'];

function buildHelpText(programName) {
  return [
    `usage: ${programName} [-h] --a A --b B --c C`,
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ].join('\n');
}

function buildErrorText(programName, message) {
  return [
    `usage: ${programName} [-h] --a A --b B --c C`,
    `${programName}: error: ${message}`,
  ].join('\n');
}

function isNegativeNumberToken(token) {
  return /^-\d+(?:_\d+)*$/.test(token);
}

function parseInteger(optionName, rawValue, programName) {
  const normalized = String(rawValue).trim();

  if (!/^[+-]?\d+(?:_\d+)*$/.test(normalized)) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `argument ${optionName}: invalid int value: '${rawValue}'`));
  }

  return Number(normalized.replace(/_/g, ''));
}

function readOptionValue(optionName, tokens, index, programName) {
  const nextToken = tokens[index + 1];

  if (nextToken === undefined) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `argument ${optionName}: expected one argument`));
  }

  if (nextToken.startsWith('-') && !isNegativeNumberToken(nextToken)) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `argument ${optionName}: expected one argument`));
  }

  return { value: nextToken, nextIndex: index + 1 };
}

function assignOption(values, optionName, rawValue, programName) {
  if (optionName === '--a' || optionName === '--b') {
    values[optionName.slice(2)] = parseInteger(optionName, rawValue, programName);
    return;
  }

  values.c = rawValue;
}

export function parseCli(argv) {
  const programName = basename(argv[1] ?? 'test8.mjs') || 'test8.mjs';
  const tokens = argv.slice(2);

  for (const token of tokens) {
    if (token === '-h' || token === '--help') {
      throw new CliExit(0, 'stdout', buildHelpText(programName));
    }
  }

  const values = {};
  const unknownTokens = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--') {
      unknownTokens.push(...tokens.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');

      if (equalsIndex !== -1) {
        const optionName = token.slice(0, equalsIndex);
        const rawValue = token.slice(equalsIndex + 1);

        if (OPTION_NAMES.includes(optionName)) {
          assignOption(values, optionName, rawValue, programName);
          continue;
        }

        unknownTokens.push(token);
        continue;
      }

      if (OPTION_NAMES.includes(token)) {
        const { value, nextIndex } = readOptionValue(token, tokens, index, programName);
        assignOption(values, token, value, programName);
        index = nextIndex;
        continue;
      }

      unknownTokens.push(token);
      continue;
    }

    if (token.startsWith('-')) {
      unknownTokens.push(token);
      continue;
    }

    unknownTokens.push(token);
  }

  const missing = OPTION_NAMES.filter((optionName) => values[optionName.slice(2)] === undefined);

  if (missing.length > 0) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `the following arguments are required: ${missing.join(', ')}`));
  }

  if (unknownTokens.length > 0) {
    throw new CliExit(2, 'stderr', buildErrorText(programName, `unrecognized arguments: ${unknownTokens.join(' ')}`));
  }

  return values;
}

export function isCliExit(error) {
  return error instanceof CliExit;
}

