import { isCliExit, parseCli } from './cli_parser.mjs';
import {
  buildFixedLengthBytes,
  buildInt8ul,
  encodeUtf8,
  getPythonStringLength,
  isConstructBuildError,
} from './construct_like.mjs';
import { formatPythonBytes } from './python_bytes_repr.mjs';

function writeLine(stream, value) {
  stream.write(`${value}\n`);
}

function renderConstructError(error) {
  return `construct.core.${error.kind}: ${error.detail}`;
}

export function main(argv = process.argv) {
  try {
    const args = parseCli(argv);
    const format1 = buildInt8ul(args.a);
    const format2 = buildInt8ul(args.b);
    const length = getPythonStringLength(args.c);
    const format3 = buildFixedLengthBytes(length, encodeUtf8(args.c));

    writeLine(process.stdout, formatPythonBytes(format1));
    writeLine(process.stdout, formatPythonBytes(format2));
    writeLine(process.stdout, formatPythonBytes(format3));
    return 0;
  } catch (error) {
    if (isCliExit(error)) {
      writeLine(error.stream === 'stdout' ? process.stdout : process.stderr, error.content);
      return error.code;
    }

    if (isConstructBuildError(error)) {
      writeLine(process.stderr, renderConstructError(error));
      return 1;
    }

    throw error;
  }
}

