export function formatPythonBytes(buffer) {
  let result = "b'";

  for (const byteValue of buffer.values()) {
    if (byteValue === 0x09) {
      result += '\\t';
      continue;
    }

    if (byteValue === 0x0a) {
      result += '\\n';
      continue;
    }

    if (byteValue === 0x0d) {
      result += '\\r';
      continue;
    }

    if (byteValue === 0x5c) {
      result += '\\\\';
      continue;
    }

    if (byteValue === 0x27) {
      result += "\\'";
      continue;
    }

    if (byteValue >= 0x20 && byteValue <= 0x7e) {
      result += String.fromCharCode(byteValue);
      continue;
    }

    result += `\\x${toHex(byteValue)}`;
  }

  result += "'";
  return result;
}

