class ConstructBuildError extends Error {
  constructor(kind, detail) {
    super(detail);
    this.kind = kind;
    this.detail = detail;
  }
}

export function buildInt8ul(value) {
  if (!Number.isInteger(value) || value < 0 || value > 255) {
    throw new ConstructBuildError('FormatFieldError', `Error in path (building)\nstruct '<B' error during building, given value ${value}`);
  }

  return Buffer.from([value]);
}

export function buildFixedLengthBytes(expectedLength, bytes) {
  if (bytes.length !== expectedLength) {
    throw new ConstructBuildError('StreamError', `Error in path (building)\nbytes object of wrong length, expected ${expectedLength}, found ${bytes.length}`);
  }

  return Buffer.from(bytes);
}

export function encodeUtf8(text) {
  return Buffer.from(text, 'utf8');
}

export function getPythonStringLength(text) {
  return Array.from(text).length;
}

export function isConstructBuildError(error) {
  return error instanceof ConstructBuildError;
}

