export function basename(pathValue) {
  const normalized = String(pathValue ?? '').replace(/\\/g, '/');
  const lastSlashIndex = normalized.lastIndexOf('/');
  return lastSlashIndex === -1 ? normalized : normalized.slice(lastSlashIndex + 1);
}

export function fileUrlToPath(fileUrl) {
  const value = String(fileUrl ?? '');
  if (!value.startsWith('file://')) {
    return value;
  }

  return decodeURIComponent(value.slice('file://'.length));
}

export function normalizePath(pathValue) {
  return String(pathValue ?? '').replace(/\\/g, '/');
}

export function isDirectExecution(importMetaUrl, argvPath) {
  return normalizePath(fileUrlToPath(importMetaUrl)) === normalizePath(argvPath);
}

